# hermes-device-sync: `hermes` with no arguments = sync, resume the newest conversation from ANY of
# your devices (with its recap), and sync again when you exit. With arguments it is plain Hermes.
# `hermes-new` = plain Hermes. `sync-hermes` = sync now. Generated by setup.py; re-run setup to change.
HERMES_SYNC_SCRIPTS='__SCRIPTS__'
HERMES_SYNC_PYTHON='__PYTHON__'
sync-hermes() { "$HERMES_SYNC_PYTHON" "$HERMES_SYNC_SCRIPTS/sync.py"; }
hermes() {
  if [ "$#" -gt 0 ]; then command hermes "$@"; return; fi
  _h="$HERMES_SYNC_SCRIPTS/handoff.py"
  sync-hermes
  _id="$("$HERMES_SYNC_PYTHON" "$_h" pick 2>/dev/null | tail -n 1)"
  "$HERMES_SYNC_PYTHON" "$_h" prepare "$_id" 2>/dev/null
  if [ -n "$_id" ]; then command hermes --resume "$_id"; else command hermes -c; fi
  echo "Saving the conversation (recap + sync)..."
  "$HERMES_SYNC_PYTHON" "$_h" summarize 2>/dev/null
  sync-hermes
}
hermes-new() { command hermes "$@"; }
